using System;
using System.IO;
using System.Reflection;
using System.Collections.Generic;
using System.Web.Script.Serialization;
using System.Diagnostics;
using System.Threading;
class UpdaterTests {
 static int checks;static Type service,policy,installer;const BindingFlags All=BindingFlags.Static|BindingFlags.Instance|BindingFlags.Public|BindingFlags.NonPublic;
 static void Check(bool ok,string name){if(!ok)throw new Exception(name);checks++;Console.WriteLine("PASS "+name);}
 static object Call(Type t,string name,params object[] args){return t.GetMethod(name,All).Invoke(null,args);}
 static bool Rejected(Action action){try{action();return false;}catch(TargetInvocationException e){return e.InnerException is InvalidDataException||e.InnerException is IOException;}}
 static string Json(string tag,string url,string digest,bool preview=false){return new JavaScriptSerializer().Serialize(new{tag_name=tag,draft=false,prerelease=preview,name=tag,body="notes",assets=new[]{new{name="AirBridge.exe",browser_download_url=url,digest=digest,size=4096}}});}
 static int Main(string[] args){if(args.Length==1&&args[0]=="wait-fixture"){Thread.Sleep(1000);return 0;}try{Run(args[0]);return 0;}catch(Exception ex){Console.WriteLine("FAIL "+ex);return 1;}}
 static void Run(string root){AppDomain.CurrentDomain.AssemblyResolve+=(s,e)=>{string dependency=Path.Combine(root,new AssemblyName(e.Name).Name+".dll");return File.Exists(dependency)?Assembly.LoadFrom(dependency):null;};var asm=Assembly.LoadFrom(Path.Combine(root,"AirBridge.exe"));service=asm.GetType("AirBridge.Desktop.UpdateService");policy=asm.GetType("AirBridge.Desktop.UpdatePolicy");installer=asm.GetType("AirBridge.Desktop.UpdateInstaller");
  var defaults=(Dictionary<string,object>)Call(asm.GetType("AirBridge.Desktop.SettingsStore"),"Defaults");Check(!(bool)defaults["UpdateChecksEnabled"],"persisted settings default to no automatic checks");
  var p=Activator.CreateInstance(policy,true);var today=new DateTime(2026,11,10,12,0,0);Func<bool> automatic=()=> (bool)policy.GetMethod("CanAutomaticallyCheck",All).Invoke(p,new object[]{today});
  Check(!automatic(),"automatic checks off by default");policy.GetField("AutoCheck").SetValue(p,true);Check(automatic(),"opt-in enables automatic checks");policy.GetField("SessionSkipped").SetValue(p,true);Check(!automatic(),"session skip blocks checks");policy.GetField("SessionSkipped").SetValue(p,false);policy.GetField("SkipDate").SetValue(p,"2026-11-10");Check(!automatic(),"today skip blocks checks");Check((bool)policy.GetMethod("CanAutomaticallyCheck",All).Invoke(p,new object[]{today.AddDays(1)}),"today skip expires next day in the same session");policy.GetField("SkipDate").SetValue(p,"");policy.GetField("IgnoredTag").SetValue(p,"v3.0.66");Check(automatic(),"ignored release still permits finding future releases");Check(!(bool)policy.GetMethod("CanNotify",All).Invoke(p,new object[]{"v3.0.66"}),"ignored release does not notify");Check((bool)policy.GetMethod("CanNotify",All).Invoke(p,new object[]{"v3.0.67"}),"newer release can notify");policy.GetField("Forbidden").SetValue(p,true);Check(!automatic()&&!(bool)policy.GetMethod("CanNotify",All).Invoke(p,new object[]{"v3.0.67"}),"disabled updates block checking and notifications");
  string url="https://github.com/xxxxkq/AirBridge/releases/download/v3.0.66/AirBridge.exe",digest="sha256:"+new string('a',64);
  var found=Call(service,"Parse",Json("v3.0.66",url,digest),"3.0.65");Check(found!=null,"valid newer single-file release accepted");Check(Call(service,"Parse",Json("v3.0.65",url,digest),"3.0.65")==null,"same version not offered");Check(Call(service,"Parse",Json("v3.0.64",url,digest),"3.0.65")==null,"downgrade not offered");Check(Call(service,"Parse",Json("v3.0.66",url,digest,true),"3.0.65")==null,"prerelease not offered");Check(Rejected(()=>Call(service,"Parse",Json("v3.0.66",url,""),"3.0.65")),"missing digest rejected");Check(Rejected(()=>Call(service,"Parse",Json("v3.0.66","https://example.com/AirBridge.exe",digest),"3.0.65")),"foreign download source rejected");Check(Rejected(()=>Call(service,"Parse",Json("v3.0.66","https://github.com/xxxxkq/AirBridge/releases/download/../../../../other/repo/a.exe",digest),"3.0.65")),"normalized path escape rejected");
  string dir=Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"update-fixture-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(dir);string target=Path.Combine(dir,"app.exe"),candidate=Path.Combine(dir,"candidate.exe"),backup=target+".previous";File.WriteAllText(target,"old");File.WriteAllText(candidate,"new");
  Check(Rejected(()=>Call(installer,"Commit",candidate,target,backup,new string('0',64))),"tampered staging refused");Check(File.ReadAllText(target)=="old"&&!File.Exists(backup),"failed verification leaves original intact");string hash=(string)Call(service,"HashFile",candidate);Call(installer,"Commit",candidate,target,backup,hash);Check(File.ReadAllText(target)=="new"&&File.ReadAllText(backup)=="old","atomic replacement retains original backup");Call(installer,"Rollback",target,backup);Check(File.ReadAllText(target)=="old","rollback restores original file");Check(Directory.GetFiles(dir,"*.update-*").Length==0,"temporary staging files cleaned");
  var originalProtocol=System.Net.ServicePointManager.SecurityProtocol;try{Call(service,"ConfigureTransport");Check(System.Net.ServicePointManager.SecurityProtocol==System.Net.SecurityProtocolType.Tls12,"updater explicitly enables TLS 1.2 instead of legacy defaults");}finally{System.Net.ServicePointManager.SecurityProtocol=originalProtocol;}
  var configured=(System.Net.IWebProxy)Call(service,"SelectProxy","https://api.github.com/", "http://127.0.0.1:7897","");Check(configured.GetProxy(new Uri("https://api.github.com/")).Port==7897,"configured environment proxy is honored");Check(Call(service,"SelectProxy","https://api.github.com/","http://127.0.0.1:7897",".github.com")==null,"NO_PROXY domain bypass is honored");Check(Rejected(()=>Call(service,"SelectProxy","https://api.github.com/","socks5://localhost:1080","")),"unsupported proxy scheme is reported explicitly");
  Check((string)Call(service,"FailureCode",new System.Net.WebException("TLS",System.Net.WebExceptionStatus.SecureChannelFailure))=="tls","TLS failure distinguished from release metadata");Check((string)Call(service,"FailureCode",new System.Net.WebException("DNS",System.Net.WebExceptionStatus.NameResolutionFailure))=="dns","DNS failure distinguished");Check((string)Call(service,"FailureCode",new System.Net.WebException("certificate",System.Net.WebExceptionStatus.TrustFailure))=="certificate","certificate failure reported without bypass");Check((string)Call(service,"FailureCode",Activator.CreateInstance(asm.GetType("AirBridge.Desktop.UpdateRepositoryException"),true))=="repository-access","private or inaccessible repository distinguished from no release");
  string real=Path.Combine(root,"AirBridge.exe");Call(service,"Verify",real,Call(service,"HashFile",real),new FileInfo(real).Length,new Version("3.0.65.0"));Check(true,"executable hash size and version verification");Check((int)Call(installer,"Apply","invalid-token")==2,"invalid helper transaction rejected without starting UI");
  var fixtureStart=new ProcessStartInfo(Assembly.GetExecutingAssembly().Location,"wait-fixture"){UseShellExecute=false,CreateNoWindow=true,WindowStyle=ProcessWindowStyle.Hidden};using(var fixture=Process.Start(fixtureStart)){long ticks=fixture.StartTime.ToUniversalTime().Ticks;var watch=Stopwatch.StartNew();Call(installer,"Wait",fixture.Id+":"+(ticks+1),watch);Check(watch.ElapsedMilliseconds<500,"different process generation is not waited on");Call(installer,"Wait",fixture.Id+":"+ticks,watch);Check(fixture.HasExited,"owned process exits before installer proceeds");Call(installer,"Wait",fixture.Id+":"+ticks,Stopwatch.StartNew());Check(true,"already exited process handled without exit race failure");}
  Console.WriteLine("PASS updater total="+checks+"; no network, UI, real process termination or system output changes");
 }
}
